/*
 * QuickFi Design System — web brand engine
 * Generated by scripts/gen-web-brand.js from scripts/brand-engine-core.js +
 * tokens/values.json. Do not hand-edit: `npm run build` overwrites this file,
 * and CI fails if it has drifted.
 *
 * Re-tints the page for one credit line, from that line's seed colour. Load
 * quickfi.css first; this file writes over its colour custom properties.
 *
 *   import { applyBrand, clearBrand } from './quickfi-brand.js';
 *   applyBrand('#004C97');   // once the credit line resolves, after login
 *   clearBrand();            // back to the static, untinted tier
 *
 * Both cross-fade (350ms, 100ms under reduced motion — quickfi.css owns the
 * timing). The derivation below is the same code scripts/check-brand-
 * derivation.js proves for every registered seed and a 216-seed sweep, so a
 * seed nobody has picked yet still clears every contrast floor.
 * See tokens/brand-engine.md, "App integration contract".
 */

// ------------------------------------------------------------------ engine
// scripts/brand-engine-core.js, verbatim.
/**
 * THE ALGORITHM, WITH NO I/O. scripts/brand-engine.js binds it to
 * tokens/values.json for Node; scripts/gen-web-brand.js embeds this file
 * VERBATIM in platforms/web/quickfi-brand.js for the browser. One source, so
 * web cannot drift from what check-brand-derivation.js proves. It must never
 * require() anything — the browser has no module to give it.
 *
 * Runtime brand engine — derives the credit-line accent/container tier from a
 * single seed colour, in OKLCH. See tokens/brand-engine.md for the full
 * design rationale; this file is the algorithm the doc describes.
 *
 * WHY THIS EXISTS
 * ---------------
 * Every static token in tokens/values.json is hand-audited, one pairing at a
 * time, in tokens/audit.json. That does not scale to an open-ended list of
 * partner brand colours (Partner Blue-1, Partner Red-1, whoever signs next) chosen for
 * marketing reasons, not accessibility ones. So this tier is NOT authored —
 * it is computed, once per credit line, at app runtime, and the contrast
 * guarantee lives in the algorithm rather than in a hand-checked table.
 * scripts/check-brand-derivation.js is what proves the guarantee holds, both
 * for the seeds in tokens/credit-lines.json and for seeds nobody has picked
 * yet.
 *
 * WHAT IT PRODUCES
 * ----------------
 * Given one seed hex, returns { light: {...}, dark: {...} } where each mode
 * carries:
 *   container/background, container/surface, container/surface-1,
 *   container/surface-2, container/subsurface  — the SAME identifiers as
 *     the static tier, each given a faint wash of the credit line's hue at
 *     its own existing lightness step — only the chroma changes, and by
 *     design it barely does: this is what keeps a credit line's app feeling
 *     like its own thing (a mood, not just an accent dropped on top of a
 *     generic shell) without touching the dark-ladder or separation
 *     guarantees the static tier already proved.
 *   action/selected          — the SAME identifier as the static tier: the
 *     selection wash under a selected row, chip or tab, and the pressed fill
 *     of an OUTLINE/TEXT button. Given the credit line's hue at the tonal-
 *     card chroma cap — a step more colour than the ambient surface wash
 *     above, because it has to read as a deliberate selection ON those
 *     surfaces rather than as more of them. Its lightness stays where the
 *     static token put it unless an obligation forces a move; see
 *     findSelectedL for the obligation that usually does, in dark mode.
 *   brand/accent, brand/accent-hover, brand/accent-pressed  — chip fills, an
 *     emphasis/progress bar. Never a button fill — see tokens/source.js's
 *     Action-and-border group for why FILLED stays brand-agnostic NEUTRAL.
 *     Hover/pressed are NOT independently derived tones — they're the base
 *     accent composited with a fixed-opacity state layer (Material 3's
 *     mechanism), so there is one colour to reason about per credit line,
 *     not three.
 *   text/on-brand            — label on a brand/accent fill.
 *   brand/background         — one MORE tinted tonal surface, deliberately
 *     more saturated than the ambient container wash above — a credit-line
 *     hero card or program switcher. Nowhere else. (Named to avoid colliding
 *     with the static container/background token — this one lives only in
 *     this runtime output, never in tokens/values.json.)
 *   text/on-brand-background — label on brand/background.
 *   text/link, border/focus  — the SAME identifiers the static tier already
 *     defines. The app overrides them in place once a credit line resolves;
 *     tokens/values.json's text/link and border/focus values are the neutral
 *     fallback used before that.
 *
 * WHAT IT DELIBERATELY DOES NOT TOUCH
 * ------------------------------------
 * Every text/* role except text/link, every feedback/* status colour, and
 * action/filled/* for every intent — including action/filled/disabled. Those
 * are shared across every credit line, on purpose: accessibility, legibility
 * and status meaning are not a partner's to retheme. (Container surfaces and
 * action/selected get the credit line's hue, per the above — but every one of
 * them is proven not to touch the contrast or separation floors below.)
 *
 * action/selected USED to be in this list, on the reasoning that selection is
 * a state rather than a surface and so not a brand moment. It is derived now
 * because that reasoning produced a measurable bug once the container wash
 * landed: a neutral grey wash on hue-washed surfaces reads as absence of
 * colour, i.e. as disabled — and in dark mode the static token sat 1.005:1
 * from action/filled/disabled (#494844 vs #494950), a pairing nothing in
 * tokens/audit.json had ever measured because neither token is on top of the
 * other. checkDerivation now measures it; findSelectedL is what satisfies it.
 */

// ------------------------------------------------------------------ colour math
// Standard sRGB <-> linear <-> OKLab <-> OKLCH round trip (Björn Ottosson's
// formulas). Kept self-contained and dependency-free, same constraint as the
// rest of this repo.
const hexToRgb = hex => {
  const n = parseInt(hex.replace('#', ''), 16);
  return [(n >> 16 & 255) / 255, (n >> 8 & 255) / 255, (n & 255) / 255];
};
const rgbToHex = ([r, g, b]) => {
  const c = v => Math.round(Math.max(0, Math.min(1, v)) * 255).toString(16).padStart(2, '0');
  return '#' + (c(r) + c(g) + c(b)).toUpperCase();
};
const srgbToLinear = c => (c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4));
const linearToSrgb = c => (c <= 0.0031308 ? c * 12.92 : 1.055 * Math.pow(Math.max(c, 0), 1 / 2.4) - 0.055);

function rgbToOklab(rgb) {
  const [r, g, b] = rgb.map(srgbToLinear);
  const l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b;
  const m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b;
  const s = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b;
  const l_ = Math.cbrt(l), m_ = Math.cbrt(m), s_ = Math.cbrt(s);
  return [
    0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
    1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
    0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_,
  ];
}
function oklabToRgb([L, a, b]) {
  const l_ = L + 0.3963377774 * a + 0.2158037573 * b;
  const m_ = L - 0.1055613458 * a - 0.0638541728 * b;
  const s_ = L - 0.0894841775 * a - 1.2914855480 * b;
  const l = l_ ** 3, m = m_ ** 3, s = s_ ** 3;
  const r = +4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s;
  const g = -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s;
  const bl = -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s;
  return [r, g, bl].map(linearToSrgb);
}
const oklabToOklch = ([L, a, b]) => {
  const C = Math.sqrt(a * a + b * b);
  let H = Math.atan2(b, a) * 180 / Math.PI;
  if (H < 0) H += 360;
  return [L, C, H];
};
const oklchToOklab = ([L, C, H]) => [L, C * Math.cos(H * Math.PI / 180), C * Math.sin(H * Math.PI / 180)];

const hexToOklch = hex => oklabToOklch(rgbToOklab(hexToRgb(hex)));

/** OKLCH -> sRGB hex, reducing chroma until the colour is back in gamut. A
 * seed's raw (L, C, H) triple frequently lands outside sRGB once L is pushed
 * toward an accessible tone — this is the standard chroma-clamp fix rather
 * than letting channels silently clip and drift the hue. */
function oklchToHexInGamut(L, C, H) {
  let c = C;
  for (let i = 0; i < 40; i++) {
    const rgb = oklabToRgb(oklchToOklab([L, c, H]));
    if (rgb.every(v => v >= -0.0015 && v <= 1.0015)) return rgbToHex(rgb);
    c *= 0.92;
  }
  return rgbToHex(oklabToRgb(oklchToOklab([L, 0, H]))); // fully desaturated fallback
}

// ------------------------------------------------------------------ WCAG contrast
// Same formula as scripts/validate.js, kept independent so this file has no
// import-order dependency on it.
function relLuminance(hex) {
  const [r, g, b] = hexToRgb(hex).map(srgbToLinear);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function contrast(hexA, hexB) {
  const a = relLuminance(hexA), b = relLuminance(hexB);
  const [lo, hi] = a < b ? [a, b] : [b, a];
  return (hi + 0.05) / (lo + 0.05);
}

// ------------------------------------------------------------------ tuning
const TEXT_MIN = 4.5;    // text/link, on-accent, on-container
const GRAPHIC_MIN = 3.0; // hover/pressed fills, focus ring as a boundary
const SEP_MIN = 1.10;    // container/page/raised/sunken vs. their neighbour — house floor
const ACCENT_CHROMA_CAP = 0.14;    // "muted" — regardless of how saturated the seed is
const CONTAINER_CHROMA_CAP = 0.05; // visibly tinted; a card, not a fill
const SURFACE_TINT_CHROMA_CAP = 0.02; // barely-there wash across page/raised/sunken
// Material 3's state-layer opacities: a fixed-alpha scrim over the base
// colour, not a second derived tone. Light mode scrims toward black (darker
// states), dark mode toward white — the same direction the static intents
// already use, just composited instead of independently searched.
const STATE_LAYER = { hover: 0.08, pressed: 0.12 };
// The page wash: two radial glows of the credit line's hue, one anchored at
// the top-left corner and one at the bottom-right, each fading out through a
// haze ring. DARK MODE ONLY — see deriveWash for why light cannot carry it. The
// geometry is a contract, not a per-platform choice, the same way BRAND_SWAP_MS
// is: one glow radius, one haze position, one fade-out edge, everywhere.
// Replaced the 150deg linear band on 2026-09-25 — the band read as a stripe
// across the page; two glows that meet in the middle read as light.
const WASH = {
  chromaCap: 0.045,   // a hue deepening over the page's own 0.02 surface tint
  hazeAlpha: 0.60,    // black, composited over the page — see deriveWash
  glow: {
    radiusPct: 120,   // each glow's radius as % of the page's own size — past centre, so the two overlap
    hazePct: 75,      // where the haze ring sits, as % of the glow radius
    edgePct: 100,     // where the glow has faded fully to the page, as % of the glow radius
  },
};
const clampL = v => Math.max(0.02, Math.min(0.98, v));

const WHITE = '#FFFFFF', NEAR_BLACK = '#0B0A0F';
/** Whichever of near-black or white reads better on this fill — same rule
 * figma-plugin/code.js's onColour() uses for hero-card labels. */
function bestLabel(fillHex) {
  return contrast(fillHex, NEAR_BLACK) >= contrast(fillHex, WHITE) ? NEAR_BLACK : WHITE;
}

/** Search lightness at fixed (C, H) for the least extreme value that still
 * clears TEXT_MIN against both page and raised. "Least extreme" means: in
 * light mode, the LIGHTEST value that still passes (minimum necessary
 * darkening); in dark mode, the DARKEST value that still passes (minimum
 * necessary lightening). That is what keeps the result reading as "the
 * brand hue, muted" instead of "the brand hue, forced to an extreme". */
function findAccentL(C, H, page, raised, mode) {
  if (mode === 'light') {
    for (let L = 0.90; L >= 0.04; L -= 0.01) {
      const hex = oklchToHexInGamut(L, C, H);
      if (contrast(hex, page) >= TEXT_MIN && contrast(hex, raised) >= TEXT_MIN) return L;
    }
    return 0.04;
  }
  for (let L = 0.10; L <= 0.96; L += 0.01) {
    const hex = oklchToHexInGamut(L, C, H);
    if (contrast(hex, page) >= TEXT_MIN && contrast(hex, raised) >= TEXT_MIN) return L;
  }
  return 0.96;
}

/** Composite `overlayHex` over `baseHex` at `alpha`, in sRGB — the same space
 * a browser blends a translucent `rgba()` scrim in, which is what this is
 * standing in for: a state layer, not a second derived tone. */
function overlay(baseHex, overlayHex, alpha) {
  const base = hexToRgb(baseHex), top = hexToRgb(overlayHex);
  return rgbToHex(base.map((b, i) => b * (1 - alpha) + top[i] * alpha));
}

/**
 * The page wash, as two OPAQUE hexes so no alpha ever crosses this boundary:
 *
 *   wash — the corner tone. The seed's HUE at the page's OWN lightness, chroma
 *     stepped to WASH.chromaCap. Never the seed itself: a primitive bound into
 *     a surface is what this system exists to prevent, and at chroma 0.14-0.24
 *     a raw seed reads as a colour field rather than a wash. Holding the page's
 *     lightness is what keeps it legible — a corner that varies lightness eats
 *     text/tertiary, which has 0.07 of headroom on the light page.
 *   haze — the mid-band, black at WASH.hazeAlpha composited over the page.
 *     Pre-composited rather than passed as an alpha stop so that every platform
 *     paints four opaque stops and nothing has to agree about blend modes.
 *
 * LIGHT MODE RETURNS THE PAGE FOR BOTH, so the gradient every platform paints
 * is flat in light with no conditional anywhere: all its stops resolve to
 * container/background. That is arithmetic, not preference. container/surface
 * is pure #FFFFFF, the lightness ceiling, so the light page sits at L 0.959 and
 * sRGB has almost no chroma left that close to white — the most a light corner
 * can reach is the chroma the page already has (0.020 for blue and red hues,
 * i.e. the same hex). Only green keeps gamut room up there, and washing light
 * for whichever partners' hues happen to allow it would make the brand
 * treatment depend on hue.
 */
function deriveWash(seedC, H, pageHex, mode) {
  if (mode !== 'dark') return { wash: pageHex, haze: pageHex };
  const [L] = hexToOklch(pageHex);
  return {
    wash: oklchToHexInGamut(L, Math.min(seedC, WASH.chromaCap), H),
    haze: overlay(pageHex, '#000000', WASH.hazeAlpha),
  };
}

/** Tint a static surface hex toward the credit line's hue, at a fixed
 * lightness (never move the tonal ladder, only add a wash of colour). Near-
 * white surfaces (light-mode container/surface is pure #FFFFFF) are
 * self-limiting here: chroma is out of gamut at L=1 regardless of the cap,
 * so oklchToHexInGamut clamps it back toward white on its own — cards stay
 * close to neutral while background and subsurface pick up a visible wash. */
function tintSurface(hex, H) {
  const [L] = hexToOklch(hex);
  return oklchToHexInGamut(L, SURFACE_TINT_CHROMA_CAP, H);
}

/** The selection wash's lightness. action/selected's OWN static lightness is
 * tried first — the tonal ladder never moves for free — and kept if the hue-
 * tinted result still satisfies every obligation the token carries:
 *
 *   - text/primary on it at TEXT_MIN (tokens/audit.json's "text/primary on
 *     selected"),
 *   - SEP_MIN against tinted container/surface AND container/surface-1, the
 *     two layers a selected row actually sits on,
 *   - SEP_MIN against action/filled/disabled, which is NOT brand-derived and
 *     does not move. This is the obligation that did not exist before this
 *     tier: nothing audited the two against each other, because neither is
 *     ever rendered on top of the other — they are only ever confused with
 *     each other, which is not a contrast pairing any table was looking for.
 *
 * Otherwise it takes the smallest step away from that lightness that does,
 * preferring the direction the surface ladder already uses per mode (darker
 * in light, lighter in dark).
 */
function findSelectedL(C, H, staticHex, surface, surface1, textPrimary, disabled, mode) {
  const baseL = hexToOklch(staticHex)[0];
  const preferredDir = mode === 'light' ? -1 : 1;
  const holds = hex => contrast(hex, textPrimary) >= TEXT_MIN
    && contrast(hex, surface) >= SEP_MIN
    && contrast(hex, surface1) >= SEP_MIN
    && contrast(hex, disabled) >= SEP_MIN;
  for (let delta = 0; delta <= 0.5; delta += 0.02) {
    const dirs = delta === 0 ? [1] : [preferredDir, -preferredDir];
    for (const dir of dirs) {
      const L = clampL(baseL + dir * delta);
      if (holds(oklchToHexInGamut(L, C, H))) return L;
    }
  }
  return clampL(baseL + preferredDir * 0.5);
}

/** The selected-TEXT wash's lightness. Same search as findSelectedL against a
 * different set of layers, not a reuse of its answer: a selected row sits on
 * container/surface or surface-1, selected text sits in the container/
 * subsurface well of an input. The obligations are therefore
 *
 *   - text/primary on it at TEXT_MIN (the pairing Material never audits, and
 *     the reason an unbound selection wash is a risk on a recessed field),
 *   - SEP_MIN against tinted container/subsurface, the well it sits in,
 *   - SEP_MIN against tinted container/surface, since an input can sit
 *     directly on a card with no well of its own.
 *
 * Across every seed swept so far the static lightness already holds and only
 * chroma moves. The search is here for the seed that eventually does not.
 */
function findSelectionBgL(C, H, staticHex, subsurface, surface, textPrimary, mode) {
  const baseL = hexToOklch(staticHex)[0];
  const preferredDir = mode === 'light' ? -1 : 1;
  const holds = hex => contrast(hex, textPrimary) >= TEXT_MIN
    && contrast(hex, subsurface) >= SEP_MIN
    && contrast(hex, surface) >= SEP_MIN;
  for (let delta = 0; delta <= 0.5; delta += 0.02) {
    const dirs = delta === 0 ? [1] : [preferredDir, -preferredDir];
    for (const dir of dirs) {
      const L = clampL(baseL + dir * delta);
      if (holds(oklchToHexInGamut(L, C, H))) return L;
    }
  }
  return clampL(baseL + preferredDir * 0.5);
}

/** The brand/background tonal card's lightness: the smallest step away from
 * container/surface's own lightness — in either direction — that clears the
 * SEP_MIN separation floor. Ties prefer the same direction
 * container/subsurface already uses per mode (darker in light, lighter in
 * dark), for visual consistency with the rest of the surface ladder. */
function findBrandBackgroundL(C, H, surfaceHex, mode) {
  const surfaceL = hexToOklch(surfaceHex)[0];
  const preferredDir = mode === 'light' ? -1 : 1;
  for (let delta = 0.02; delta <= 0.5; delta += 0.02) {
    for (const dir of [preferredDir, -preferredDir]) {
      const L = clampL(surfaceL + dir * delta);
      const hex = oklchToHexInGamut(L, C, H);
      if (contrast(hex, surfaceHex) >= SEP_MIN) return L;
    }
  }
  return clampL(surfaceL + preferredDir * 0.5);
}

/**
 * Derive the full brand-derived token set for one seed, in both modes.
 * @param {string} seedHex — the credit line's brand colour, e.g. from
 *   tokens/credit-lines.json.
 * @param {{light: object, dark: object}} color — the static tier,
 *   tokens/values.json's `color`, that every derived value is tinted from.
 * @returns {{light: object, dark: object}}
 */
function deriveBrandTokens(seedHex, color) {
  const [, seedC, H] = hexToOklch(seedHex);
  const out = { light: {}, dark: {} };

  ['light', 'dark'].forEach(mode => {
    // Tint every structural container surface first — accent and the tonal
    // card are then derived against the surfaces the app will actually
    // render, not the untinted static ones, so the whole palette is checked
    // as it will really appear together.
    const background = tintSurface(color[mode]['container/background'], H);
    // Dark container/surface stays STATIC. Feedback on the branded dark theme
    // was that everything carrying the hue read as overwhelming; the card is
    // the one surface that can drop out without breaking a floor (measured
    // 1.12-1.18:1 over every derived dark page, 1.12-1.14 over surface-1).
    // Light surface still goes through tintSurface, where pure white
    // self-limits it to near-neutral anyway. 2026-09-24.
    const surface = mode === 'dark'
      ? color.dark['container/surface']
      : tintSurface(color[mode]['container/surface'], H);
    const surface1 = tintSurface(color[mode]['container/surface-1'], H);
    const surface2 = tintSurface(color[mode]['container/surface-2'], H);
    const subsurface = tintSurface(color[mode]['container/subsurface'], H);
    const scrim = mode === 'light' ? '#000000' : '#FFFFFF'; // state-layer colour

    const accentC = Math.min(seedC, ACCENT_CHROMA_CAP);
    const accentL = findAccentL(accentC, H, background, surface, mode);
    const accentHex = oklchToHexInGamut(accentL, accentC, H);
    const hoverHex = overlay(accentHex, scrim, STATE_LAYER.hover);
    const pressedHex = overlay(accentHex, scrim, STATE_LAYER.pressed);

    const textPrimary = color[mode]['text/primary'];

    // Selection carries the credit line's hue at the tonal-card chroma cap,
    // not the ambient surface cap — it has to read as a deliberate selection
    // ON those washed surfaces, not as one more of them.
    const selectedC = Math.min(seedC, CONTAINER_CHROMA_CAP);
    const selectedL = findSelectedL(
      selectedC, H, color[mode]['action/selected'],
      surface, surface1, textPrimary, color[mode]['action/filled/disabled'], mode,
    );
    const selectedHex = oklchToHexInGamut(selectedL, selectedC, H);

    const selBgC = Math.min(seedC, CONTAINER_CHROMA_CAP);
    const selBgL = findSelectionBgL(
      selBgC, H, color[mode]['text/selection-bg'],
      subsurface, surface, textPrimary, mode,
    );
    const selBgHex = oklchToHexInGamut(selBgL, selBgC, H);

    const wash = deriveWash(seedC, H, background, mode);

    const bgCardC = Math.min(seedC, CONTAINER_CHROMA_CAP);
    const bgCardL = findBrandBackgroundL(bgCardC, H, surface, mode);
    const bgCardHex = oklchToHexInGamut(bgCardL, bgCardC, H);
    const onBgCard = contrast(bgCardHex, textPrimary) >= TEXT_MIN ? textPrimary : bestLabel(bgCardHex);

    out[mode] = {
      'container/background': background,
      'container/surface': surface,
      'container/surface-1': surface1,
      'container/surface-2': surface2,
      'container/subsurface': subsurface,
      'action/selected': selectedHex,
      'brand/accent': accentHex,
      'brand/accent-hover': hoverHex,
      'brand/accent-pressed': pressedHex,
      'text/on-brand': bestLabel(accentHex),
      'brand/background': bgCardHex,
      'text/on-brand-background': onBgCard,
      // Overrides of the static fallback — same identifiers, brand tone.
      'text/link': accentHex,
      'border/focus': accentHex,
      // A caret is the focus ring in another shape. Same value by definition,
      // not by coincidence — if one of these ever stops equalling the other,
      // the control is telling the user two different things at once.
      'text/cursor': accentHex,
      'text/selection-bg': selBgHex,
      // The page wash. Both equal container/background in light, so the
      // gradient is flat there — see deriveWash.
      'container/background-wash': wash.wash,
      'container/background-wash-haze': wash.haze,
    };
  });

  return out;
}

/** Validate one derived token set against its own guarantees. Returns an
 * array of problem strings — empty means every obligation held. Used by
 * both check-brand-derivation.js and, defensively, by callers who want to
 * assert before applying a theme rather than trusting the algorithm blind. */
function checkDerivation(seedHex, tokens, color) {
  const problems = [];
  ['light', 'dark'].forEach(mode => {
    const t = tokens[mode];
    // The tinted surfaces THIS seed actually produced — not the static
    // untinted ones. Everything below is checked against what will really
    // be on screen together.
    const background = t['container/background'];
    const surface = t['container/surface'];
    const surface1 = t['container/surface-1'];
    const surface2 = t['container/surface-2'];
    const subsurface = t['container/subsurface'];
    const textPrimary = color[mode]['text/primary'];
    const textSecondary = color[mode]['text/secondary'];
    const textTertiary = color[mode]['text/tertiary'];
    const check = (label, ratio, min) => {
      if (ratio < min) problems.push(`${seedHex} ${mode}: ${label} is ${ratio.toFixed(2)}:1, needs ${min}:1`);
    };
    // Surface tint must not disturb any existing separation pairing — the
    // same set the static tier audits in tokens/audit.json, checked here
    // against the tinted values instead of the untinted ones.
    check('surface vs background (separation)', contrast(surface, background), SEP_MIN);
    check('surface-1 vs surface (separation)', contrast(surface1, surface), SEP_MIN);
    check('surface-1 vs background (separation)', contrast(surface1, background), SEP_MIN);
    check('surface-2 vs surface-1 (separation)', contrast(surface2, surface1), SEP_MIN);
    check('surface-2 vs background (separation)', contrast(surface2, background), SEP_MIN);
    check('subsurface vs surface (separation)', contrast(subsurface, surface), SEP_MIN);
    // The selection wash keeps every obligation the static token carried, and
    // one the static tier never measured: distinctness from the disabled fill.
    // action/filled/disabled is not brand-derived, so this is a derived value
    // measured against a fixed one — see findSelectedL.
    const selected = t['action/selected'];
    const disabledFill = color[mode]['action/filled/disabled'];
    check('action/selected vs tinted surface (separation)', contrast(selected, surface), SEP_MIN);
    check('action/selected vs tinted surface-1 (separation)', contrast(selected, surface1), SEP_MIN);
    check('action/selected vs action/filled/disabled (separation)', contrast(selected, disabledFill), SEP_MIN);
    check('text/primary vs action/selected', contrast(color[mode]['text/primary'], selected), TEXT_MIN);
    // action/selected is the only derived token whose LIGHTNESS can move (every
    // other one keeps its static step and changes chroma only), so it is the
    // only one that can fall through the dark ladder — no dark value may be
    // darker than container/background dark, or it reads as a hole. That rule
    // lives in scripts/validate.js, which only ever sees static values, so the
    // derived wash has to assert it for itself.
    if (mode === 'dark' && relLuminance(selected) < relLuminance(background)) {
      problems.push(`${seedHex} dark: action/selected (${selected}) is darker than container/background (${background}) — it would read as a hole, not a selection`);
    }
    // The caret is the accent, same as border/focus, so it inherits the
    // accent's own guarantees against background and surface. What it does
    // NOT inherit is subsurface: an input well is darker than the page in
    // light mode, so the accent has less to work against there than anywhere
    // the accent search itself looked. Rated as a graphic — a caret is a thin
    // mark, not something anyone reads.
    const cursor = t['text/cursor'];
    check('text/cursor vs tinted subsurface', contrast(cursor, subsurface), GRAPHIC_MIN);
    check('text/cursor vs tinted surface', contrast(cursor, surface), GRAPHIC_MIN);
    check('text/cursor vs tinted background', contrast(cursor, background), GRAPHIC_MIN);
    if (cursor !== t['border/focus']) {
      problems.push(`${seedHex} ${mode}: text/cursor (${cursor}) and border/focus (${t['border/focus']}) have diverged — a caret and a focus ring are one signal and must resolve to one value`);
    }
    // The selected-text wash carries the pairing Material never audits.
    const selBg = t['text/selection-bg'];
    check('text/primary vs text/selection-bg', contrast(textPrimary, selBg), TEXT_MIN);
    check('text/selection-bg vs tinted subsurface (separation)', contrast(selBg, subsurface), SEP_MIN);
    check('text/selection-bg vs tinted surface (separation)', contrast(selBg, surface), SEP_MIN);
    // Same reasoning as action/selected above: this token's lightness can move,
    // so the dark ladder has to be asserted here rather than in validate.js.
    if (mode === 'dark' && relLuminance(selBg) < relLuminance(background)) {
      problems.push(`${seedHex} dark: text/selection-bg (${selBg}) is darker than container/background (${background}) — a selection that reads as a hole`);
    }
    // text/tertiary is not rated on surface-1/surface-2 even statically — see
    // tokens/source.js's Container group — so it is deliberately excluded
    // here too, not just on background/surface.
    [['text/primary', textPrimary], ['text/secondary', textSecondary], ['text/tertiary', textTertiary]]
      .forEach(([name, hex]) => {
        check(`${name} vs tinted background`, contrast(hex, background), TEXT_MIN);
        check(`${name} vs tinted surface`, contrast(hex, surface), TEXT_MIN);
      });
    [['text/primary', textPrimary], ['text/secondary', textSecondary]]
      .forEach(([name, hex]) => {
        check(`${name} vs tinted surface-1`, contrast(hex, surface1), TEXT_MIN);
        check(`${name} vs tinted surface-2`, contrast(hex, surface2), TEXT_MIN);
      });
    check('text/link (accent) vs tinted background', contrast(t['text/link'], background), TEXT_MIN);
    check('text/link (accent) vs tinted surface', contrast(t['text/link'], surface), TEXT_MIN);
    check('text/on-brand vs brand/accent', contrast(t['text/on-brand'], t['brand/accent']), TEXT_MIN);
    check('brand/accent-hover vs tinted surface', contrast(t['brand/accent-hover'], surface), GRAPHIC_MIN);
    check('brand/accent-pressed vs tinted surface', contrast(t['brand/accent-pressed'], surface), GRAPHIC_MIN);
    // The state layers carry the SAME label as the base accent — text/on-brand
    // is picked once, against brand/accent, and does not get re-picked when a
    // chip is hovered or pressed. So the label has a contrast obligation
    // against the hover and pressed fills too, not just the base. It holds by
    // construction (the state layer darkens in light mode where the label is
    // light, and lightens in dark mode where the label is dark, so it moves
    // AWAY from the label in both) — which is exactly why it is asserted here
    // rather than left as a property of the current STATE_LAYER opacities. A
    // future tweak to those opacities, or to the near-black/white pick in
    // step 6, would otherwise break this silently.
    check('text/on-brand vs brand/accent-hover', contrast(t['text/on-brand'], t['brand/accent-hover']), TEXT_MIN);
    check('text/on-brand vs brand/accent-pressed', contrast(t['text/on-brand'], t['brand/accent-pressed']), TEXT_MIN);
    check('brand/background vs tinted surface (separation)', contrast(t['brand/background'], surface), SEP_MIN);
    check('text/on-brand-background vs brand/background', contrast(t['text/on-brand-background'], t['brand/background']), TEXT_MIN);
    // Label polarity must not flip between the static fallback and the derived
    // value. This is what makes the cross-fade in tokens/brand-engine.md's app
    // integration contract safe to run on ALL fourteen fields at once: both
    // label tokens are a near-black/white pick, so a flip would send the label
    // through mid-grey mid-transition, where it has no contrast guarantee
    // against a fill that is itself mid-transition. Both endpoints are audited
    // (static in tokens/audit.json, derived above) and neither says anything
    // about t=0.5. Holds today for every registered and swept seed — the
    // derived pick lands on the same pole as the fallback every time — so the
    // contract can specify one simultaneous fade rather than sequencing the
    // labels separately.
    ['text/on-brand', 'text/on-brand-background'].forEach(name => {
      const staticHex = color[mode][name];
      if ((relLuminance(t[name]) > 0.5) !== (relLuminance(staticHex) > 0.5)) {
        problems.push(`${seedHex} ${mode}: ${name} flips polarity across the swap (${staticHex} static -> ${t[name]} derived) — a cross-fade would pass through mid-grey`);
      }
    });
    // The page wash. Both bands are the PAGE ITSELF in a darker or hue-shifted
    // region, so every obligation the page carries applies to them: text has to
    // read on them, and a card has to separate from them. Checked across both
    // bands rather than the mean, because a card can sit anywhere along the
    // gradient.
    //
    // The dark-ladder rule is deliberately NOT applied to the haze. It is
    // black composited over the page, so it IS darker than
    // container/background — which for any other token would mean "reads as a
    // hole". A hole is a thing that looks recessed FROM the page; the haze is
    // part of the page, and it moves every obligation in the safe direction
    // (light text gains contrast, cards gain separation). Asserting the ladder
    // here would forbid the feature for no accessibility gain.
    ['container/background-wash', 'container/background-wash-haze'].forEach(band => {
      const hex = t[band];
      const name = band.replace('container/background-', '');
      if (mode !== 'dark') {
        if (hex !== background) {
          problems.push(`${seedHex} light: ${band} (${hex}) is not container/background (${background}) — the light wash must be flat, since sRGB has no chroma left at the light page's lightness`);
        }
        return;
      }
      [['text/primary', textPrimary], ['text/secondary', textSecondary], ['text/tertiary', textTertiary]]
        .forEach(([role, ink]) => check(`${role} vs ${name}`, contrast(ink, hex), TEXT_MIN));
      check(`surface vs ${name} (separation)`, contrast(surface, hex), SEP_MIN);
      check(`surface-1 vs ${name} (separation)`, contrast(surface1, hex), SEP_MIN);
      check(`surface-2 vs ${name} (separation)`, contrast(surface2, hex), SEP_MIN);
    });
    if (t['text/link'] === textPrimary) problems.push(`${seedHex} ${mode}: accent collapsed onto text/primary — seed may be too close to neutral`);
  });
  return problems;
}

/**
 * The tuning constants as one object — what the Inspector reads its wash
 * geometry and chroma cap from (as `BE`). It used to be serialised into the
 * Inspector's DATA and re-enumerated by three scripts; now the Inspector runs
 * this file and calls it directly.
 */
const INSPECTOR_CONSTANTS = () => ({
  TEXT_MIN, GRAPHIC_MIN, SEP_MIN,
  ACCENT_CHROMA_CAP, CONTAINER_CHROMA_CAP,
  SURFACE_TINT_CHROMA_CAP, STATE_LAYER,
  WASH,
});

// Guarded: this file is also inlined into an ES module, where `module` does
// not exist.
if (typeof module !== "undefined") module.exports = {
  deriveBrandTokens, checkDerivation, contrast, hexToOklch, oklchToHexInGamut,
  INSPECTOR_CONSTANTS,
  TEXT_MIN, GRAPHIC_MIN, SEP_MIN, ACCENT_CHROMA_CAP, CONTAINER_CHROMA_CAP,
  SURFACE_TINT_CHROMA_CAP, STATE_LAYER, WASH,
};

