// ------------------------------------------------------------------ browser
const SEED = /^#?[0-9a-fA-F]{6}$/;
const STYLE_ID = 'qf-brand';
const SWAP_ATTR = 'data-qf-brand-swap';
let swapTimer;

// The seed arrives in a login response, so it is checked rather than trusted:
// a malformed hex would otherwise derive NaN into every colour.
function derive(seedHex) {
  if (typeof seedHex !== 'string' || !SEED.test(seedHex)) {
    throw new TypeError(`quickfi-brand: seed must be a 6-digit hex colour, got ${JSON.stringify(seedHex)}`);
  }
  return deriveBrandTokens('#' + seedHex.replace('#', '').toUpperCase(), STATIC);
}

const block = mode => Object.entries(mode)
  .map(([name, hex]) => `--qf-${name.replace(/\//g, '-')}:${hex};`).join('');

// The same three selectors quickfi.css flips modes with, in the same order and
// at the same specificity, so whichever mode wins there wins here. Never an
// inline style on :root — that would beat [data-theme="dark"] and paint the
// light values in both modes.
const css = t =>
  `:root{${block(t.light)}}` +
  `[data-theme="dark"]{${block(t.dark)}}` +
  `@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){${block(t.dark)}}}`;

function swap(cssText) {
  const root = document.documentElement;
  root.setAttribute(SWAP_ATTR, '');
  let el = document.getElementById(STYLE_ID);
  if (cssText === null) {
    if (el) el.remove();
  } else {
    if (!el) {
      el = document.createElement('style');
      el.id = STYLE_ID;
    }
    el.textContent = cssText;
    // Re-appended every time: last in <head> is what puts it after
    // quickfi.css at equal specificity, however late that stylesheet loaded.
    document.head.appendChild(el);
  }
  // The attribute carries the transition, so it stays on for the length of
  // the fade and no longer — left on, a light/dark toggle would fade too.
  const style = getComputedStyle(root);
  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const ms = parseFloat(style.getPropertyValue(reduced ? '--qf-brand-swap-reduced' : '--qf-brand-swap')) || 0;
  clearTimeout(swapTimer);
  swapTimer = setTimeout(() => root.removeAttribute(SWAP_ATTR), ms + 50);
}

/** Cross-fade the page to one credit line's derived tier. Returns the derived
 *  tokens ({ light, dark }) for anything that needs a value in script. */
function applyBrand(seedHex) {
  const tokens = derive(seedHex);
  swap(css(tokens));
  return tokens;
}

/** Cross-fade back to the static tier — logout, or a program-less screen. */
function clearBrand() {
  swap(null);
}

export { applyBrand, clearBrand, derive as deriveBrandTokens };
